# Reporting views (Postgres). OD and approved medical leave count as present.
V_ATTENDANCE_SUMMARY = """
CREATE VIEW v_attendance_summary AS
SELECT e.student_id,
       e.semester_id,
       e.course_id,
       COUNT(a.id) AS total_classes,
       COUNT(a.id) FILTER (WHERE a.status IN ('present', 'od', 'medical')) AS attended,
       ROUND(100.0 * COUNT(a.id) FILTER (WHERE a.status IN ('present', 'od', 'medical'))
             / NULLIF(COUNT(a.id), 0), 2) AS attendance_pct
FROM enrollments e
LEFT JOIN attendance a ON a.enrollment_id = e.id
GROUP BY e.student_id, e.semester_id, e.course_id
"""

V_STUDENT_OVERVIEW = """
CREATE VIEW v_student_overview AS
SELECT s.id AS student_id,
       s.roll_no,
       s.name,
       s.department_id,
       s.section,
       s.current_semester,
       (SELECT sr.cgpa_upto
          FROM semester_results sr
          JOIN semesters sm ON sm.id = sr.semester_id
         WHERE sr.student_id = s.id
         ORDER BY sm.number DESC
         LIMIT 1) AS cgpa,
       (SELECT ROUND(100.0 * SUM(v.attended) / NULLIF(SUM(v.total_classes), 0), 2)
          FROM v_attendance_summary v
          JOIN semesters sm ON sm.id = v.semester_id
         WHERE v.student_id = s.id AND sm.number = s.current_semester) AS attendance_pct,
       (SELECT COUNT(*)
          FROM (SELECT e.course_id, MAX(cr.grade_points) AS best
                  FROM course_results cr
                  JOIN enrollments e ON e.id = cr.enrollment_id
                 WHERE e.student_id = s.id
                 GROUP BY e.course_id) b
         WHERE b.best = 0) AS active_backlogs,
       (SELECT COUNT(*)
          FROM assignment_submissions sub
         WHERE sub.student_id = s.id AND sub.status IN ('submitted', 'late', 'graded')) AS assignments_submitted
FROM students s
"""
